@startuml

class HospitalHouseMD {
  + name : string
}

class Patient {
  + name : string
  + symptoms : string
}

class Doctor {
  + name : string
  + specialization : string
}

class HeadDoctor {
  + name : string
}

class Diagnosis {
  + description : string
  + date : date
}

class Treatment {
  + name : string
  + description : string
}

class TreatmentStage {
  + level : int
}

class ConsentForm {
  + signatureDate : date
  + status : string
}

class Illness {
  + name : string
  + priorityScore : PriorityScore
}

enum PriorityScore {
  HIGH
  LOW
}

HospitalHouseMD "1" o-- "1..*" Patient
Patient "1" -- "1..*" Doctor
Doctor "1" -- "1..*" Diagnosis
Diagnosis "1" -- "1..*" Treatment
HospitalHouseMD "1" -- "1..*" Treatment
HeadDoctor "1" -- "0..*" Diagnosis : approves
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "0..*" Treatment : authorizes
Treatment "1" *-- "1" TreatmentStage
Illness "1" -- "1..*" Diagnosis
Illness "1" -- "1..*" Treatment

@enduml

